      return mcqQ("Hàng đợi lần lượt enqueue " + b.join(", ") + ", rồi dequeue một lần, rồi enqueue " + z + ". Phần tử ở đầu hàng đợi lúc này là gì?", [String(out), String(z)], String(front), "Dequeue lấy " + out + " vào trước nhất ra; phần tử vào tiếp theo là " + front + " lên đầu hàng.");
